const base = process.env.QA_BASE_URL || 'http://127.0.0.1:5199';
const scope = process.env.QA_ONLY || 'full';
const requestedMatch=process.env.QA_MATCH||null;
const match=requestedMatch?new RegExp(requestedMatch):null;
const viewports = [[320,568],[375,667],[390,844],[412,915],[768,1024],[1024,768],[1440,900],[1920,1080]];
const routes = [['home','/'],['marketplace','/beli'],['item','/barang/sora'],['condition','/barang/sora?tab=condition'],['room','/barang/sora?tab=room'],['capture','/barang/sora?tab=guide'],['checkout','/checkout/sora'],['jual','/jual'],['barang-saya','/barang-saya'],['saved','/tersimpan']];
const forbiddenCopy = /\b(?:prototype|prototipe|demo|simulasi|engine)\b|—|minta\s+foto\s+(?:tambahan|lagi)|(?:kamera|foto)\s+(?:nyata|asli)|rekonstruksi\s+(?:selesai|berhasil)|pembayaran\s+berhasil/gi;
const results = {scope,requestedMatch,started:new Date().toISOString(),checks:[],layouts:[],screenshots:[],mediaAttempts:[],pageErrors:[],consoleErrors:[],missingAssets:[],externalRequests:[],requestFailures:[],diagnosticSnapshots:[],javascript:[],expectedFallbackDiagnostics:[]};
let stopRequested=false;
process.on('SIGINT',()=>{stopRequested=true;console.log('STOP_REQUESTED after current check');});
process.on('SIGTERM',()=>{stopRequested=true;console.log('STOP_REQUESTED after current check');});
await fs.mkdir(output,{recursive:true});
const hash = text => createHash('sha256').update(text).digest('hex');
async function sourceManifest() {
  const src = await fs.readdir(path.join(root,'src'));
  return Object.fromEntries(await Promise.all(['index.html','package.json',...src.filter(name=>/\.(?:js|css)$/.test(name)).map(name=>'src/'+name)].map(async name=>[name,hash(await fs.readFile(path.join(root,name)))])));
}
results.sourceBefore = await sourceManifest();
const server = process.env.QA_BASE_URL ? null : await createServer({root,server:{host:'127.0.0.1',port:5199,strictPort:true}});
await server?.listen();
const browser = await chromium.launch({executablePath:await testBrowserPath(),headless:true,args:['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--disable-dev-shm-usage']});
const pending = new Set();
function observeContext(context, expected = false) {
  context.setDefaultTimeout(60000);context.setDefaultNavigationTimeout(60000);
  context.on('page', page=>{
    page.on('pageerror',e=>(expected?results.expectedFallbackDiagnostics:results.pageErrors).push({url:page.url(),message:e.message}));
    page.on('console',m=>{if(m.type()==='error')(expected?results.expectedFallbackDiagnostics:results.consoleErrors).push({url:page.url(),message:m.text()});});
    page.on('response',r=>{
      if(r.status()>=400)(expected?results.expectedFallbackDiagnostics:results.missingAssets).push({url:r.url(),status:r.status()});
      if(!expected && /(?:\.[cm]?js)(?:\?|$)/.test(r.url()) && r.url().startsWith(base)) {
        const task = r.text().then(code=>results.javascript.push({url:r.url(),hash:hash(code),bytes:code.length,forbidden:code.match(/getUserMedia|getDisplayMedia|(?:src\/|\.\/)(?:seller|media-store)\.js|type\s*=\s*["']file["']/g)||[]})).catch(()=>{});
        pending.add(task);task.finally(()=>pending.delete(task));
      }
    });
    page.on('request',r=>{if(!r.url().startsWith(base)&&!r.url().startsWith('data:')&&!r.url().startsWith('blob:'))results.externalRequests.push(r.url());});
    page.on('requestfailed',r=>results.requestFailures.push({page:page.url(),url:r.url(),error:r.failure()?.errorText,expected}));
    page.on('filechooser',()=>results.mediaAttempts.push({url:page.url(),api:'filechooser'}));
  });
}
async function instrument(context) {
  await context.exposeBinding('__recordPreparedMediaAttempt',({page},attempt)=>results.mediaAttempts.push({url:page.url(),...attempt}));
  await context.addInitScript(()=>{
    const record=(api,detail)=>{const item={api,detail:String(detail??'')};(window.__preparedMediaAttempts??=[]).push(item);void window.__recordPreparedMediaAttempt(item);};
    const blocked=api=>(...args)=>{record(api,args[0]?.name);return Promise.reject(new DOMException('Media access is forbidden in prepared QA.','NotAllowedError'));};
    let devices=navigator.mediaDevices;
    if(!devices){devices={};try{Object.defineProperty(navigator,'mediaDevices',{configurable:true,value:devices});}catch{}}
    for(const name of ['getUserMedia','getDisplayMedia'])try{Object.defineProperty(devices,name,{configurable:true,writable:true,value:blocked('mediaDevices.'+name)});}catch{}
    for(const name of ['getUserMedia','webkitGetUserMedia','mozGetUserMedia'])try{Object.defineProperty(navigator,name,{configurable:true,value:(...args)=>{record('navigator.'+name);args.at(-1)?.(new DOMException('Media blocked.','NotAllowedError'));}});}catch{}
    const permissions=navigator.permissions;
    if(permissions)for(const name of ['query','request'])try{Object.defineProperty(permissions,name,{configurable:true,value:blocked('permissions.'+name)});}catch{}
    const originalClick=HTMLInputElement.prototype.click;
    HTMLInputElement.prototype.click=function(...args){if(this.type==='file'){record('fileInput.click');return;}return originalClick.apply(this,args);};
    const originalPicker=HTMLInputElement.prototype.showPicker;
    if(originalPicker)HTMLInputElement.prototype.showPicker=function(...args){if(this.type==='file'){record('fileInput.showPicker');return;}return originalPicker.apply(this,args);};
    document.addEventListener('click',e=>{const input=e.target.closest?.('input[type="file"]');const label=e.target.closest?.('label[for]');if(input || label&&document.getElementById(label.htmlFor)?.type==='file'){record('fileInput.userClick');e.preventDefault();}},true);
  });
}
const context = await browser.newContext({viewport:{width:1440,height:900},hasTouch:true});
observeContext(context);await instrument(context);
const page = await context.newPage();page.setDefaultTimeout(60000);page.setDefaultNavigationTimeout(60000);
const check = async(name,fn)=>{
  const guard=/^(?:loaded public JavaScript|zero camera|source is frozen|no JavaScript page errors|no normal-route console errors|no missing normal-route assets|no unexpected external requests)/.test(name);
  if(match&&!guard&&!match.test(name))return;
  try{const evidence=await fn();results.checks.push({name,pass:true,evidence});console.log('PASS',name);}
  catch(e){results.checks.push({name,pass:false,error:e.stack||e.message});console.log('FAIL',name,e.message);}
  await fs.writeFile(path.join(output,'progress.json'),JSON.stringify(results,null,2));
};
async function open(route, target = page, {model=true}={}) {
  await target.goto(base+route,{waitUntil:'networkidle'});await target.locator('#main').waitFor();
  const stage=target.locator('.inspection-stage');
  if(model && await stage.count()) {await stage.locator('canvas').waitFor({timeout:60000});await stage.locator('.inspection-loading').waitFor({state:'hidden',timeout:60000});assert.equal(await target.locator('.inspection-error').isVisible(),false,'Model load failed');}
  if(['/jual','/buat','/barang-saya'].includes(route.split('?')[0])||route.includes('tab=guide')) {
    await target.locator('[data-prepared-count]').waitFor();
    if(model && await target.locator('[data-prepared-workspace]').isVisible()) {await target.locator('[data-prepared-stage] canvas').waitFor({timeout:60000});await target.locator('.prepared-loading').waitFor({state:'hidden',timeout:60000});assert.equal(await target.locator('.prepared-stage-error').isVisible(),false,'Prepared model load failed');}
  }
}
async function readyRenderedModel(target=page) {
  await target.locator('.inspection-stage canvas').waitFor({timeout:60000});
  await target.locator('.inspection-loading').waitFor({state:'hidden',timeout:60000});
  await target.waitForFunction(()=>{const e=window.lihatDulu?.engine||document.querySelector('.inspection')?._engine;return Boolean(e?.ready&&e.renderer.info.render.triangles>0);},null,{timeout:60000});
}
async function nextRenderedFrame(target=page) {await target.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));}
async function screenshot(name,target=page) {
  const lazy=target.locator('img[loading="lazy"]');
  for(let i=0;i<await lazy.count();i++){const img=lazy.nth(i);if(await img.isVisible()){await img.scrollIntoViewIfNeeded();await img.evaluate(e=>e.decode().catch(()=>{}));assert.ok(await img.evaluate(e=>e.naturalWidth>0),'Lazy image did not decode: '+await img.getAttribute('src'));}}
  await target.evaluate(()=>window.scrollTo(0,0));
  const filename=path.join(output,name+'.png');await target.screenshot({path:filename,fullPage:true,timeout:60000});results.screenshots.push({name,path:filename});return filename;
}
async function scan(name,target=page) {
  const layout=await target.evaluate(()=>{
    const visible=e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity)>.01;};
    const scrollingAncestor=e=>{for(let p=e.parentElement;p;p=p.parentElement)if(['auto','scroll'].includes(getComputedStyle(p).overflowX))return p.className;return null;};
    const offscreen=[...document.querySelectorAll('a,button,input,select,textarea,[tabindex="0"]')].filter(visible).map(e=>({name:e.getAttribute('aria-label')||e.textContent.trim().slice(0,70),rect:e.getBoundingClientRect().toJSON(),scrollParent:scrollingAncestor(e)})).filter(e=>(e.rect.left<-.6||e.rect.right>innerWidth+.6)&&!e.scrollParent);
    const broken=[...document.images].filter(i=>visible(i)&&i.complete&&!i.naturalWidth).map(i=>i.src);
    return{width:innerWidth,height:innerHeight,scrollWidth:document.documentElement.scrollWidth,offscreenInteractive:offscreen,brokenImages:broken,text:document.body.innerText,fileInputs:document.querySelectorAll('input[type="file"]').length,mediaAttempts:window.__preparedMediaAttempts||[]};
  });
  layout.forbidden=layout.text.match(forbiddenCopy)||[];delete layout.text;layout.name=name;results.layouts.push(layout);
  assert.ok(layout.scrollWidth<=layout.width+1,JSON.stringify(layout));assert.deepEqual(layout.offscreenInteractive,[],JSON.stringify(layout));assert.deepEqual(layout.brokenImages,[],JSON.stringify(layout));assert.deepEqual(layout.forbidden,[],JSON.stringify(layout));assert.equal(layout.fileInputs,0,'A public file-upload control is present');assert.deepEqual(layout.mediaAttempts,[],'Public route requested a media/permission API');
  return layout;
}
async function engineState(target=page) {
  return target.evaluate(()=>{
    const engine=window.lihatDulu?.engine||document.querySelector('.inspection')?._engine||document.querySelector('[data-prepared-capture]')?._engine;
    if(!engine?.model||!engine.camera||!engine.controls)throw new Error('Actual readable engine camera, controls, and GLB model are required.');
    const nodes=Object.fromEntries(['left_door_pivot','right_door_pivot','drawer_slide'].map(name=>{const node=engine.model.getObjectByName(name);if(!node)throw new Error('Missing authored GLB node '+name);return[name,{rotation:node.rotation.toArray().slice(0,3),position:node.position.toArray()}];}));
    const room=engine.scene.getObjectByName('illustrative_room');
    const obstacles=engine.scene.children.filter(n=>n.isMesh&&n.material?.color?.getHex()===0xd19e65&&n.visible).map(n=>({position:n.position.toArray(),scale:n.scale.toArray()}));
    return{state:engine.getState(),camera:engine.camera.position.toArray(),target:engine.controls.target.toArray(),nodes,modelPosition:engine.model.position.toArray(),roomVisible:room?.visible??false,obstacles,triangles:engine.renderer.info.render.triangles};
  });
}
async function settledEngine(target=page) {await target.waitForTimeout(750);return engineState(target);}
const closeTo=(a,b,tolerance=.003)=>assert.ok(Math.abs(a-b)<tolerance,`${a} differs from ${b} by more than ${tolerance}`);
async function expandControl(selector,target=page){const control=target.locator(selector);if(!await control.isVisible()){const ancestors=await control.evaluate(e=>{const list=[];for(let p=e.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS'&&!p.open)list.push([...document.querySelectorAll('details')].indexOf(p));return list.reverse();});for(const index of ancestors)await target.locator('details').nth(index).locator(':scope > summary').click();}return control;}
async function setRange(kind,value){const input=await expandControl(`[data-motion="${kind}"]`);await input.focus();await input.press('Home');for(let i=0;i<value;i++)await input.press('ArrowRight');return settledEngine();}
async function outcomes(){return page.locator('[data-placement]').evaluateAll(nodes=>Object.fromEntries(nodes.map(e=>[e.dataset.placement,e.dataset.clear??null])));}
async function resetPrepared(){await page.locator('[data-prepared-action="reset"]').click();const confirm=page.locator('[data-prepared-action="reset-confirm"],[data-action="prepared-reset-confirm"]');if(await confirm.isVisible())await confirm.click();}
